/**
 * Forge handler — serves the /forge/metrics and /forge/layout routes.
 *
 * /forge/metrics: queries CloudWatch for the specific metrics chosen by the
 * layout (generated by Bedrock). Only fetches what the dashboard needs.
 *
 * /forge/layout: discovers deployed stack resources via CloudFormation,
 * builds a metric catalog scoped to the resource types present, sends it
 * to Bedrock to design a dashboard layout. Cached in S3 until the stack
 * resource fingerprint changes.
 */
import {
  CloudFormationClient,
  DescribeStackResourcesCommand,
  DescribeStacksCommand,
  DeleteStackCommand,
} from "@aws-sdk/client-cloudformation";
import {
  CloudWatchClient,
  GetMetricDataCommand,
} from "@aws-sdk/client-cloudwatch";
import {
  BedrockRuntimeClient,
  ConverseCommand,
} from "@aws-sdk/client-bedrock-runtime";
import {
  S3Client,
  GetObjectCommand,
  PutObjectCommand,
} from "@aws-sdk/client-s3";
import {
  APIGatewayClient,
  GetRestApiCommand,
} from "@aws-sdk/client-api-gateway";
import { CloudFrontClient } from "@aws-sdk/client-cloudfront";
import { createHash } from "node:crypto";
import { reconcileFromPointer } from "../agent/deployRecord.js";

const REGION = process.env.AWS_REGION || "us-east-1";
const BUCKET = process.env.BUCKET_NAME || "";
const MODEL_ID = process.env.ANALYZER_MODEL_ID ?? "eu.anthropic.claude-sonnet-4-6";

/** The tags every agent deploy puts on its stack (deployMcp.ts). The stack's
 *  env carries the key so the two sides cannot drift apart silently. */
const DEPLOY_TAG_KEY = process.env.DEPLOY_TAG_KEY || "KiroFlockManaged";
const DEPLOY_TAG_VALUE = process.env.DEPLOY_TAG_VALUE || "true";
const DEPLOY_GROUP_TAG_KEY = "KiroFlockGroup";
const DEFAULT_GROUP_TAG = "default";

const cfn = new CloudFormationClient({ region: REGION });
const cw = new CloudWatchClient({ region: REGION });
const bedrock = new BedrockRuntimeClient({ region: REGION });
const s3 = new S3Client({ region: REGION });
const apigw = new APIGatewayClient({ region: REGION });
// Only used when reconciling a missing deployment record, to resolve a
// CloudFront-fronted site URL for stacks that declare no URL output.
const cloudfront = new CloudFrontClient({ region: REGION });

// ---- Metric catalog ----
// Three categories: traffic (incoming requests), compute (execution), data (storage/throughput).
// Only default CloudWatch metrics that emit automatically. Verified against AWS docs.

interface MetricDef {
  namespace: string;
  metricName: string;
  /** Primary dimension name. */
  dimensionName: string;
  /** Additional static dimensions required by CloudWatch. */
  extraDimensions?: Record<string, string>;
  stat: "Sum" | "Average";
  label: string;
  category: "traffic" | "compute" | "data";
  /**
   * How to resolve the dimension value from CloudFormation's PhysicalResourceId.
   * - "physical" (default): use the physical ID directly.
   * - "rest-api-name": call GetRestApi to look up the display name from the API ID.
   * - "alb-suffix": extract the portion after "loadbalancer/" from the full ARN (format: app/name/hash).
   * - "sqs-queue-name": extract the last path segment from the queue URL.
   * - "ecs-service": extract ClusterName and ServiceName from the service ARN. Sets both dimensions.
   * - "arn-last-segment": extract the last segment after : or / from an ARN.
   */
  dimensionSource?: "physical" | "rest-api-name" | "alb-suffix" | "sqs-queue-name" | "ecs-service" | "arn-last-segment";
}

const METRIC_CATALOG: Record<string, MetricDef[]> = {
  // ---- Traffic: incoming requests/connections ----
  "AWS::ApiGatewayV2::Api": [
    // HTTP API. Dimension ApiId = physical resource ID directly.
    { namespace: "AWS/ApiGateway", metricName: "Count", dimensionName: "ApiId", stat: "Sum", label: "Requests", category: "traffic" },
  ],
  "AWS::ApiGateway::RestApi": [
    // REST API. Dimension ApiName = display name (not the API ID). Requires GetRestApi lookup.
    { namespace: "AWS/ApiGateway", metricName: "Count", dimensionName: "ApiName", stat: "Sum", label: "Requests", category: "traffic", dimensionSource: "rest-api-name" },
  ],
  "AWS::ElasticLoadBalancingV2::LoadBalancer": [
    // ALB. Dimension LoadBalancer = "app/name/hash" (suffix of ARN after "loadbalancer/").
    { namespace: "AWS/ApplicationELB", metricName: "RequestCount", dimensionName: "LoadBalancer", stat: "Sum", label: "Requests", category: "traffic", dimensionSource: "alb-suffix" },
  ],
  "AWS::CloudFront::Distribution": [
    // CloudFront. Dimension DistributionId = physical resource ID directly.
    { namespace: "AWS/CloudFront", metricName: "Requests", dimensionName: "DistributionId", stat: "Sum", label: "Requests", category: "traffic" },
  ],
  "AWS::SQS::Queue": [
    // SQS. Dimension QueueName = last path segment of queue URL. Physical ID is the full URL.
    { namespace: "AWS/SQS", metricName: "NumberOfMessagesSent", dimensionName: "QueueName", stat: "Sum", label: "Messages Sent", category: "traffic", dimensionSource: "sqs-queue-name" },
  ],

  // ---- Compute: execution/utilization ----
  "AWS::Lambda::Function": [
    // Lambda. Dimension FunctionName = physical resource ID directly.
    { namespace: "AWS/Lambda", metricName: "Invocations", dimensionName: "FunctionName", stat: "Sum", label: "Invocations", category: "compute" },
  ],
  "AWS::EC2::Instance": [
    // EC2. Dimension InstanceId = physical resource ID directly.
    { namespace: "AWS/EC2", metricName: "CPUUtilization", dimensionName: "InstanceId", stat: "Average", label: "CPU %", category: "compute" },
  ],
  "AWS::ECS::Service": [
    // ECS. Dimensions ClusterName + ServiceName extracted from service ARN.
    { namespace: "AWS/ECS", metricName: "CPUUtilization", dimensionName: "ServiceName", stat: "Average", label: "CPU %", category: "compute", dimensionSource: "ecs-service" },
  ],
  "AWS::StepFunctions::StateMachine": [
    // Step Functions. Dimension StateMachineArn = physical resource ID (the full ARN). Works directly.
    { namespace: "AWS/States", metricName: "ExecutionsStarted", dimensionName: "StateMachineArn", stat: "Sum", label: "Executions", category: "compute" },
  ],

  // ---- Data: storage and throughput ----
  "AWS::DynamoDB::Table": [
    // DynamoDB. Dimension TableName = physical resource ID directly.
    { namespace: "AWS/DynamoDB", metricName: "ConsumedWriteCapacityUnits", dimensionName: "TableName", stat: "Sum", label: "Write Units", category: "data" },
    { namespace: "AWS/DynamoDB", metricName: "ConsumedReadCapacityUnits", dimensionName: "TableName", stat: "Sum", label: "Read Units", category: "data" },
  ],
  "AWS::RDS::DBInstance": [
    // RDS. Dimension DBInstanceIdentifier = physical resource ID directly.
    { namespace: "AWS/RDS", metricName: "DatabaseConnections", dimensionName: "DBInstanceIdentifier", stat: "Average", label: "Connections", category: "data" },
    { namespace: "AWS/RDS", metricName: "WriteIOPS", dimensionName: "DBInstanceIdentifier", stat: "Average", label: "Write IOPS", category: "data" },
  ],
  "AWS::S3::Bucket": [
    // S3 request metrics (requires bucket.addMetric({id:'AllRequests'}) in CDK).
    // Dimension BucketName = physical resource ID. FilterId = "AllRequests" per the orchestration skill guidance.
    { namespace: "AWS/S3", metricName: "PutRequests", dimensionName: "BucketName", extraDimensions: { FilterId: "AllRequests" }, stat: "Sum", label: "Put Requests", category: "data" },
    { namespace: "AWS/S3", metricName: "GetRequests", dimensionName: "BucketName", extraDimensions: { FilterId: "AllRequests" }, stat: "Sum", label: "Get Requests", category: "data" },
  ],
  "AWS::Kinesis::Stream": [
    // Kinesis. Dimension StreamName = physical resource ID directly.
    { namespace: "AWS/Kinesis", metricName: "IncomingRecords", dimensionName: "StreamName", stat: "Sum", label: "Incoming Records", category: "data" },
  ],
  "AWS::SNS::Topic": [
    // SNS. Dimension TopicName = last segment of ARN after ":". Physical ID is the full ARN.
    { namespace: "AWS/SNS", metricName: "NumberOfMessagesPublished", dimensionName: "TopicName", stat: "Sum", label: "Messages Published", category: "data", dimensionSource: "arn-last-segment" },
  ],
};

// ---- Helpers ----

function timeRangeToSeconds(range: string): number {
  switch (range) {
    case "6h": return 6 * 3600;
    case "24h": return 24 * 3600;
    default: return 3600;
  }
}

function periodForRange(range: string): number {
  switch (range) {
    case "6h": return 300;
    case "24h": return 900;
    default: return 60;
  }
}

function fingerprint(resources: { type: string; logicalId: string }[]): string {
  const sorted = resources.map(r => `${r.type}:${r.logicalId}`).sort().join("|");
  return createHash("sha256").update(sorted).digest("hex").substring(0, 16);
}

// ---- Stack discovery from deployment records ----

/**
 * Resolve the stack name backing a deployment group.
 *
 * `deployed/latest.json` is the primary source. When it is absent this used to
 * return null, which made `handleMetrics` and `handleLayout` return empty
 * payloads — no stack button, no monitoring grid, no graphs — on a stack that
 * was perfectly healthy. That is the blank Continuous Deployment view.
 *
 * So a missing record is now treated as work to do rather than an answer:
 * reconcile from the deploy intent pointer, which writes the record from
 * CloudFormation state if the stack has settled. Either way we come back with
 * the stack name, so the dashboard renders even mid-deploy.
 */
async function findStackName(group: string | null): Promise<string | null> {
  const prefix = group ? `environment/${group}/deployed/` : "environment/deployed/";
  const key = `${prefix}latest.json`;
  try {
    const resp = await s3.send(new GetObjectCommand({ Bucket: BUCKET, Key: key }));
    const body = await resp.Body?.transformToString();
    if (body) {
      const data = JSON.parse(body);
      const stackName = data.stackName || data.stack_name || null;
      if (stackName) return stackName;
    }
  } catch { /* no record — fall through to reconciliation */ }

  const reconciled = await reconcileFromPointer(
    { s3, cfn, cloudfront, bucket: BUCKET },
    group,
  );
  return reconciled?.stackName ?? null;
}

// ---- Describe stack resources (shared) ----

async function describeStack(stackName: string): Promise<{ type: string; logicalId: string; physicalId: string }[]> {
  const desc = await cfn.send(new DescribeStackResourcesCommand({ StackName: stackName }));
  return (desc.StackResources || []).map((r) => ({
    type: r.ResourceType || "",
    logicalId: r.LogicalResourceId || "",
    physicalId: r.PhysicalResourceId || "",
  }));
}

// ---- Metrics handler ----

export async function handleMetrics(group: string | null, timeRange: string): Promise<Record<string, unknown>> {
  const stackName = await findStackName(group);
  if (!stackName) {
    return { panels: {}, error: "No stack found. Ensure deployed/latest.json contains a stackName field." };
  }

  let resources: { type: string; logicalId: string; physicalId: string }[];
  try {
    resources = await describeStack(stackName);
  } catch (err: unknown) {
    return { panels: {}, error: `CloudFormation error: ${err instanceof Error ? err.message : err}` };
  }

  // Check layout cache for the panel metric selections
  const cacheKey = `store/forge/${group ?? "default"}/layout.json`;
  let layoutPanels: { metrics: string[] }[] | null = null;
  try {
    const cached = await s3.send(new GetObjectCommand({ Bucket: BUCKET, Key: cacheKey }));
    const body = await cached.Body?.transformToString();
    if (body) {
      const parsed = JSON.parse(body);
      layoutPanels = parsed.panels || null;
    }
  } catch { /* no layout cache, query all available metrics */ }

  // Build set of metric keys the layout wants (or all if no layout)
  const requestedMetricKeys = new Set<string>();
  if (layoutPanels) {
    for (const panel of layoutPanels) {
      for (const m of (panel.metrics || [])) requestedMetricKeys.add(m);
    }
  }

  // Build metric queries from the catalog for resources in the stack.
  // Resolves dimension values based on the metric definition's dimensionSource.
  const queries: { id: string; label: string; namespace: string; metricName: string; stat: string; dimensions: Record<string, string> }[] = [];
  let qIdx = 0;

  // Cache REST API name lookups (physicalId -> name)
  const restApiNameCache: Record<string, string | null> = {};

  for (const resource of resources) {
    const defs = METRIC_CATALOG[resource.type];
    if (!defs || defs.length === 0) continue;
    for (const def of defs) {
      const metricKey = `${def.namespace}/${def.metricName}`;
      if (requestedMetricKeys.size > 0 && !requestedMetricKeys.has(metricKey)) continue;

      // Resolve dimension value based on dimensionSource
      const dimensions: Record<string, string> = {};
      const source = def.dimensionSource || "physical";

      switch (source) {
        case "physical":
          // Use physical resource ID directly (Lambda FunctionName, EC2 InstanceId, etc.)
          dimensions[def.dimensionName] = resource.physicalId;
          break;

        case "rest-api-name":
          // REST API: physical ID is API ID, need to look up display name
          if (!(resource.physicalId in restApiNameCache)) {
            try {
              const apiResp = await apigw.send(new GetRestApiCommand({ restApiId: resource.physicalId }));
              restApiNameCache[resource.physicalId] = apiResp.name || null;
            } catch {
              restApiNameCache[resource.physicalId] = null;
            }
          }
          dimensions[def.dimensionName] = restApiNameCache[resource.physicalId] || resource.physicalId;
          break;

        case "alb-suffix":
          // ALB: physical ID is full ARN, dimension wants "app/name/hash" (after "loadbalancer/")
          {
            const match = resource.physicalId.match(/loadbalancer\/(.+)$/);
            dimensions[def.dimensionName] = match ? match[1] : resource.physicalId;
          }
          break;

        case "sqs-queue-name":
          // SQS: physical ID is queue URL (https://sqs.region.amazonaws.com/account/name)
          {
            const parts = resource.physicalId.split("/");
            dimensions[def.dimensionName] = parts[parts.length - 1] || resource.physicalId;
          }
          break;

        case "ecs-service":
          // ECS: physical ID is ARN (arn:aws:ecs:region:account:service/cluster-name/service-name)
          {
            const arnParts = resource.physicalId.split("/");
            // ARN format: .../cluster-name/service-name
            const serviceName = arnParts[arnParts.length - 1] || resource.physicalId;
            const clusterName = arnParts[arnParts.length - 2] || "";
            dimensions["ServiceName"] = serviceName;
            if (clusterName) dimensions["ClusterName"] = clusterName;
          }
          break;

        case "arn-last-segment":
          // SNS/generic: physical ID is ARN, dimension wants the last segment after : or /
          {
            const segments = resource.physicalId.split(/[:/]/);
            dimensions[def.dimensionName] = segments[segments.length - 1] || resource.physicalId;
          }
          break;
      }

      // Add any static extra dimensions (e.g. FilterId for S3)
      if (def.extraDimensions) {
        Object.assign(dimensions, def.extraDimensions);
      }

      queries.push({
        id: `m${qIdx++}`,
        label: `${resource.logicalId}`,
        namespace: def.namespace,
        metricName: def.metricName,
        stat: def.stat,
        dimensions,
      });
    }
  }

  if (queries.length === 0) {
    return { panels: {}, resources, info: "Stack has no resources with known CloudWatch metrics." };
  }

  // Fetch from CloudWatch
  const seconds = timeRangeToSeconds(timeRange);
  const period = periodForRange(timeRange);
  const endTime = new Date();
  const startTime = new Date(endTime.getTime() - seconds * 1000);

  const batchSize = 500;
  const allResults: Record<string, { label: string; metric: string; datapoints: { timestamp: string; value: number }[] }[]> = {};

  for (let i = 0; i < queries.length; i += batchSize) {
    const batch = queries.slice(i, i + batchSize);
    const metricDataQueries = batch.map(q => ({
      Id: q.id,
      MetricStat: {
        Metric: {
          Namespace: q.namespace,
          MetricName: q.metricName,
          Dimensions: Object.entries(q.dimensions).map(([n, v]) => ({ Name: n, Value: v })),
        },
        Period: period,
        Stat: q.stat,
      },
      Label: q.label,
    }));

    try {
      const cwResp = await cw.send(new GetMetricDataCommand({
        MetricDataQueries: metricDataQueries,
        StartTime: startTime,
        EndTime: endTime,
      }));

      for (const result of cwResp.MetricDataResults || []) {
        const query = batch.find(q => q.id === result.Id);
        if (!query) continue;
        const datapoints = (result.Timestamps || []).map((ts, idx) => ({
          timestamp: ts.toISOString(),
          value: (result.Values || [])[idx] || 0,
        })).sort((a, b) => a.timestamp.localeCompare(b.timestamp));

        const metricKey = `${query.namespace}/${query.metricName}`;
        if (!allResults[metricKey]) allResults[metricKey] = [];
        allResults[metricKey].push({
          label: query.label,
          metric: metricKey,
          datapoints,
        });
      }
    } catch (err: unknown) {
      console.error("CloudWatch GetMetricData error:", err);
    }
  }

  return { panels: allResults, resources };
}

// ---- Layout handler (Bedrock) ----

export async function handleLayout(group: string | null): Promise<Record<string, unknown>> {
  const stackName = await findStackName(group);
  if (!stackName) {
    return { panels: [], summary: "No stack found" };
  }

  let resources: { type: string; logicalId: string; physicalId: string }[];
  try {
    resources = await describeStack(stackName);
  } catch {
    return { panels: [], summary: "Could not describe stack resources" };
  }

  const fp = fingerprint(resources);

  // Check cache
  const cacheKey = `store/forge/${group ?? "default"}/layout.json`;
  try {
    const cached = await s3.send(new GetObjectCommand({ Bucket: BUCKET, Key: cacheKey }));
    const body = await cached.Body?.transformToString();
    if (body) {
      const parsed = JSON.parse(body);
      if (parsed._fingerprint === fp) return parsed;
    }
  } catch { /* no cache, generate */ }

  // Build the metric menu: only include metrics for resource types in this stack
  const presentTypes = new Set(resources.map(r => r.type));
  const metricMenu: { category: string; metricKey: string; label: string; forType: string }[] = [];
  for (const [type, defs] of Object.entries(METRIC_CATALOG)) {
    if (!presentTypes.has(type)) continue;
    for (const def of defs) {
      metricMenu.push({
        category: def.category,
        metricKey: `${def.namespace}/${def.metricName}`,
        label: def.label,
        forType: type,
      });
    }
  }

  // Build Bedrock prompt
  const resourceList = resources.map(r => `- ${r.logicalId} (${r.type})`).join("\n");
  const menuByCategory: Record<string, string[]> = { traffic: [], compute: [], data: [] };
  for (const m of metricMenu) {
    const entry = `  "${m.metricKey}" — ${m.label} (from ${m.forType.split("::").pop()})`;
    menuByCategory[m.category].push(entry);
  }
  const menuText = Object.entries(menuByCategory)
    .filter(([, entries]) => entries.length > 0)
    .map(([cat, entries]) => `${cat.toUpperCase()}:\n${[...new Set(entries)].join("\n")}`)
    .join("\n\n");

  const prompt = `You are a monitoring dashboard designer. Given this CloudFormation stack, design a dashboard.

RULES:
- Create panels grouped by category: traffic, compute, data (in that order).
- You decide how many panels to include. Show what is most useful for understanding this application's health.
- Each panel must reference metrics from the AVAILABLE METRICS list below. Do not invent metric keys.
- Multiple resources of the same type should be stacked in one panel (one chart with multiple series).
- Only include a category if the stack has resources that produce metrics for it.

AVAILABLE METRICS (only use metric keys from this list):
${menuText}

STACK RESOURCES:
${resourceList}

Also generate a Mermaid architecture diagram. Rules for mermaid:
- Use graph LR
- Max 10 nodes
- Use simple square brackets: A[Label]
- No parentheses, round brackets, or stadium shapes
- No special characters in labels
- Keep labels short (max 3 words)
- Alphanumeric and underscores only for node IDs

Respond with JSON only (no markdown, no explanation):
{
  "panels": [
    {"title": "string", "category": "traffic|compute|data", "metrics": ["Namespace/MetricName"], "description": "one sentence"}
  ],
  "summary": "2-3 sentences describing what this stack does",
  "mermaid": "graph LR\\n  A[API Gateway] --> B[Lambda]\\n  ..."
}`;

  try {
    const bedrockResp = await bedrock.send(new ConverseCommand({
      modelId: MODEL_ID,
      messages: [{ role: "user", content: [{ text: prompt }] }],
      inferenceConfig: { maxTokens: 2000, temperature: 0.2 },
    }));

    const outputText = bedrockResp.output?.message?.content?.[0]?.text || "{}";
    const jsonMatch = outputText.match(/\{[\s\S]*\}/);
    const layout = jsonMatch ? JSON.parse(jsonMatch[0]) : { panels: [], summary: "" };
    layout._fingerprint = fp;
    layout._resources = resources;

    // Cache to S3
    try {
      await s3.send(new PutObjectCommand({
        Bucket: BUCKET,
        Key: cacheKey,
        Body: JSON.stringify(layout),
        ContentType: "application/json",
      }));
    } catch { /* non-fatal */ }

    return layout;
  } catch (err: unknown) {
    console.error("Bedrock layout generation failed:", err);
    // Fallback: one panel per category that has resources
    const panels: { title: string; category: string; metrics: string[]; description: string }[] = [];
    const trafficMetrics = metricMenu.filter(m => m.category === "traffic").map(m => m.metricKey);
    const computeMetrics = metricMenu.filter(m => m.category === "compute").map(m => m.metricKey);
    const dataMetrics = metricMenu.filter(m => m.category === "data").map(m => m.metricKey);
    if (trafficMetrics.length > 0) panels.push({ title: "Incoming Traffic", category: "traffic", metrics: [...new Set(trafficMetrics)], description: "Request counts" });
    if (computeMetrics.length > 0) panels.push({ title: "Compute", category: "compute", metrics: [...new Set(computeMetrics)], description: "Execution and utilization" });
    if (dataMetrics.length > 0) panels.push({ title: "Data", category: "data", metrics: [...new Set(dataMetrics)], description: "Storage and throughput" });
    return { panels, summary: `Stack with ${resources.length} resources`, mermaid: "", _fingerprint: fp, _resources: resources };
  }
}

// ---- Group cluster discovery (shared) ----

interface GroupCluster {
  id: string;
  name: string;
  algorithm: string;
  state: string;
  agents: { action: string; nextIntent: string; iteration: number }[];
}

/**
 * Find every registered cluster whose config binds it to this deployment
 * group (`everforgeGroup === group`), with live state and latest agent
 * activity. Used by the team status report and by the destroy flow (which
 * needs to warn when a deployer cluster is still running).
 *
 * Returns null when the cluster registry itself cannot be read — distinct
 * from an empty array, which means "registry fine, no clusters in group".
 */
async function findGroupClusters(group: string | null): Promise<GroupCluster[] | null> {
  let registry: { clusters: { id: string; name?: string; algorithm?: string }[] };
  try {
    const resp = await s3.send(new GetObjectCommand({ Bucket: BUCKET, Key: "clusters.json" }));
    const body = await resp.Body?.transformToString();
    registry = body ? JSON.parse(body) : { clusters: [] };
  } catch {
    return null;
  }

  // Filter to clusters in this deployment group by checking their config
  const groupClusters: GroupCluster[] = [];

  for (const cluster of registry.clusters) {
    // Read config to check everforgeGroup
    let config: Record<string, unknown> = {};
    try {
      const cfgResp = await s3.send(new GetObjectCommand({ Bucket: BUCKET, Key: `${cluster.id}/config.json` }));
      const cfgBody = await cfgResp.Body?.transformToString();
      if (cfgBody) config = JSON.parse(cfgBody);
    } catch { continue; }

    const clusterGroup = (config.everforgeGroup as string) || null;
    if (clusterGroup !== group) continue;

    // Read cluster state
    let state = "unknown";
    try {
      const stateResp = await s3.send(new GetObjectCommand({ Bucket: BUCKET, Key: `${cluster.id}/store/state.json` }));
      const stateBody = await stateResp.Body?.transformToString();
      if (stateBody) {
        const parsed = JSON.parse(stateBody);
        state = parsed.state || "unknown";
      }
    } catch { state = "stopped"; }

    // Read snapshot for agent latest entries
    const agents: { action: string; nextIntent: string; iteration: number }[] = [];
    try {
      const snapResp = await s3.send(new GetObjectCommand({ Bucket: BUCKET, Key: `${cluster.id}/store/cluster-snapshot.json` }));
      const snapBody = await snapResp.Body?.transformToString();
      if (snapBody) {
        const snap = JSON.parse(snapBody);
        for (const agent of (snap.agents || [])) {
          if (agent.lastEntry) {
            agents.push({
              action: agent.lastEntry.action || "idle",
              nextIntent: agent.lastEntry.next_intent || "",
              iteration: agent.lastEntry.iteration ?? 0,
            });
          }
        }
      }
    } catch { /* no snapshot yet */ }

    groupClusters.push({
      id: cluster.id,
      name: cluster.name || cluster.id,
      algorithm: (config.algorithm as string) || cluster.algorithm || "amorphous",
      state,
      agents,
    });
  }

  return groupClusters;
}

// ---- Status report handler (Bedrock) ----

export async function handleStatusReport(group: string | null): Promise<Record<string, unknown>> {
  const groupClusters = await findGroupClusters(group);
  if (groupClusters === null) {
    return { teams: [], error: "Could not read cluster registry" };
  }

  if (groupClusters.length === 0) {
    return { teams: [], info: "No running clusters found for this group." };
  }

  // Build Bedrock prompt
  const clusterSummaries = groupClusters.map(c => {
    const agentLines = c.agents.length > 0
      ? c.agents.map((a, i) => `    agent-${i}: "${a.action}" (next: "${a.nextIntent}", iter ${a.iteration})`).join("\n")
      : "    (no agent activity yet)";
    return `  ${c.id} (${c.name}) [${c.algorithm}, ${c.state}]:\n${agentLines}`;
  }).join("\n\n");

  const prompt = `You are a team status reporter for a multi-cluster continuous deployment. Given the latest agent activity from each cluster, produce two things:

1. A per-team status summary
2. A 2x2 matrix placing each team in a quadrant

STATUS RULES:
- Write ONE status card per cluster (team). Keep each to 1-3 sentences.
- Focus on WHAT the team is currently working on, not what went wrong.
- Do NOT report problems that are clearly self-correcting (QA feedback cycles, fix loops, idle-then-resume patterns). These are normal operation.
- If a team is idle, say so in one word. Don't speculate why.
- If a team is waiting for another team's output (no deployed URL yet, waiting for artifacts), state that briefly.
- Use present tense ("Building the CDK stack", "Testing login flow", "Generating skills").
- The audience is an operator who wants a quick glance at what each team is doing right now.
- For "health": assign a traffic light color based on how well the team is progressing:
  - "green": productive, making progress, no blockers
  - "amber": slow progress, waiting on something, or minor issues that are self-correcting
  - "red": stuck, repeated failures, blocked, or no progress for a long time
- Use the cluster ID as the name (do not rename or prettify it).

2x2 MATRIX RULES:
- X-axis: Progress (0.0 = no progress, 1.0 = fully delivered)
- Y-axis: Risk (0.0 = no risk, 1.0 = severely blocked or failing)
- Place each team as a point with x and y coordinates between 0 and 1.
- The four quadrants mean:
  - Bottom-left (low progress, low risk): "Just started" — early stages, no concerns
  - Bottom-right (high progress, low risk): "On track" — delivering well
  - Top-left (low progress, high risk): "Needs attention" — blocked or struggling
  - Top-right (high progress, high risk): "Watch closely" — delivering but fragile

CLUSTER ACTIVITY:
${clusterSummaries}

Respond with JSON only (no markdown, no explanation):
{
  "teams": [
    {"id": "cluster-id", "name": "cluster-id", "state": "running|stopped|paused|starting", "health": "green|amber|red", "status": "1-3 sentence summary of current activity"}
  ],
  "matrix": [
    {"id": "cluster-id", "x": 0.7, "y": 0.2}
  ]
}`;

  try {
    const bedrockResp = await bedrock.send(new ConverseCommand({
      modelId: MODEL_ID,
      messages: [{ role: "user", content: [{ text: prompt }] }],
      inferenceConfig: { maxTokens: 1500, temperature: 0.1 },
    }));

    const outputText = bedrockResp.output?.message?.content?.[0]?.text || "{}";
    const jsonMatch = outputText.match(/\{[\s\S]*\}/);
    const result = jsonMatch ? JSON.parse(jsonMatch[0]) : { teams: [] };
    return result;
  } catch (err: unknown) {
    console.error("Bedrock status report failed:", err);
    // Fallback: return raw cluster states without Bedrock summary
    return {
      teams: groupClusters.map(c => ({
        id: c.id,
        name: c.name,
        state: c.state,
        status: c.agents.length > 0
          ? c.agents.map(a => a.action).join("; ")
          : "No activity yet",
      })),
    };
  }
}

// ---- Destroy deployment ----

/**
 * Everything the destroy confirmation dialog needs in one call: the stack
 * backing this deployment group, its current CloudFormation status, and
 * whether any deployer cluster bound to the group is still running (a
 * running deployer may simply redeploy the stack after destruction, so the
 * UI warns but does not block).
 */
export async function handleStackInfo(group: string | null): Promise<Record<string, unknown>> {
  const stackName = await findStackName(group);
  if (!stackName) {
    return { stackName: null, error: "No stack found for this deployment group." };
  }

  // Status is advisory — a stack that is already gone still resolves a name
  // from the deployment record, and the dialog should say so rather than fail.
  let stackStatus: string | null = null;
  try {
    const desc = await cfn.send(new DescribeStacksCommand({ StackName: stackName }));
    stackStatus = desc.Stacks?.[0]?.StackStatus ?? null;
  } catch { /* stack deleted or never created */ }

  const groupClusters = (await findGroupClusters(group)) ?? [];
  const clusters = groupClusters.map((c) => ({ id: c.id, name: c.name, state: c.state }));

  return {
    stackName,
    stackStatus,
    clusters,
    deployerRunning: clusters.some((c) => c.state !== "stopped"),
  };
}

/**
 * Delete the CloudFormation stack backing a deployment group.
 *
 * Deliberately no cluster-state gate: the operator confirms in the UI (typed
 * phrase) or via the MCP confirm parameter, and a running deployer is a
 * warning, not a blocker. CloudFormation reuses the service role recorded on
 * the stack at deploy time (the CDK bootstrap cfn-exec role), so this Lambda
 * only needs cloudformation:DeleteStack — resource deletion runs with the
 * same permissions that created them.
 *
 * S3 deployment records (deployed/latest.json, changelog) are intentionally
 * left in place as the audit trail; the env panel's archive/delete actions
 * clean those up separately.
 */
export async function handleDestroy(group: string | null): Promise<Record<string, unknown>> {
  const stackName = await findStackName(group);
  if (!stackName) {
    return { error: "No stack found for this deployment group." };
  }
  // The name came from deployed/latest.json, which agents can write. Only a
  // stack this flock deployed (every agent deploy is tagged, see deployMcp.ts)
  // and deployed for this group may be deleted. The Lambda's DeleteStack grant
  // carries the same tag condition, so this check is the readable refusal in
  // front of the IAM one, not the only line.
  const tags = await stackTags(stackName);
  if (tags === null) {
    return { error: `Stack ${stackName} does not exist.` };
  }
  if (tags[DEPLOY_TAG_KEY] !== DEPLOY_TAG_VALUE) {
    return { error: `Stack ${stackName} was not deployed by this flock (no ${DEPLOY_TAG_KEY} tag); refusing to delete it.` };
  }
  const expectedGroup = group ?? DEFAULT_GROUP_TAG;
  if (tags[DEPLOY_GROUP_TAG_KEY] === undefined) {
    return { error: `Stack ${stackName} carries no ${DEPLOY_GROUP_TAG_KEY} tag, so its deployment group cannot be checked; refusing to delete it.` };
  }
  if (tags[DEPLOY_GROUP_TAG_KEY] !== expectedGroup) {
    return { error: `Stack ${stackName} belongs to deployment group "${tags[DEPLOY_GROUP_TAG_KEY]}", not "${expectedGroup}"; refusing to delete it.` };
  }
  await cfn.send(new DeleteStackCommand({ StackName: stackName }));
  return { stackName, status: "deleting" };
}

/** A stack's tags as a map, or null when there is no such stack. */
async function stackTags(stackName: string): Promise<Record<string, string> | null> {
  try {
    const desc = await cfn.send(new DescribeStacksCommand({ StackName: stackName }));
    const stack = desc.Stacks?.[0];
    if (!stack) return null;
    const out: Record<string, string> = {};
    for (const t of stack.Tags ?? []) if (t.Key) out[t.Key] = t.Value ?? "";
    return out;
  } catch (err: unknown) {
    if (/does not exist/i.test(err instanceof Error ? err.message : String(err))) return null;
    throw err;
  }
}
